"""Render access.yaml (grants/tags/retention/masks) into SQL. Deterministic."""
from __future__ import annotations

from pathlib import Path

import yaml

HERE = Path(__file__).resolve().parent
ACCESS = HERE / "access.yaml"


def load_access(path: str | Path = ACCESS) -> dict:
    return yaml.safe_load(Path(path).read_text())


def render_access_sql(access: dict) -> str:
    lines = ["-- ============================================================",
             "-- Governance as code — generated by `python -m governance access`",
             "-- Do not edit by hand; edit governance/access.yaml instead.",
             "-- ============================================================", ""]

    lines.append("-- grants")
    for group in sorted(access.get("groups", {})):
        for grant in access["groups"][group]:
            lines.append(f"GRANT {grant} TO `{group}`;")

    lines += ["", "-- tags"]
    for table in sorted(access.get("tags", {})):
        tags = access["tags"][table]
        pairs = ", ".join(f"'{k}' = '{v}'" for k, v in sorted(tags.items()))
        lines.append(f"ALTER TABLE {table} SET TAGS ({pairs});")

    lines += ["", "-- retention"]
    for table in sorted(access.get("retention", {})):
        dur = access["retention"][table]
        lines.append(f"ALTER TABLE {table} SET TBLPROPERTIES "
                     f"('delta.deletedFileRetentionDuration' = '{dur}');")

    lines += ["", "-- column masks"]
    for m in sorted(access.get("masks", []), key=lambda x: (x["table"], x["column"])):
        lines.append(f"ALTER TABLE {m['table']} ALTER COLUMN {m['column']} "
                     f"SET MASK {m['function']};")
    return "\n".join(lines) + "\n"


def apply_access(spark, access: dict) -> int:
    """Execute the rendered SQL on a Spark session (Databricks). Returns statement count."""
    stmts = [s for s in render_access_sql(access).split(";") if s.strip()
             and not s.strip().startswith("--")]
    for s in stmts:
        spark.sql(s)
    return len(stmts)
